<?php
/**
 * install_standings_timeline_v005_20260627_124649am.php
 *
 * VERSION: v001
 * LAST MODIFIED: 6/27/2026 12:46:49 am
 *
 * CHANGELOG:
 * v001 (6/27/2026 12:46:49 am)
 *   - NEW: Installer for standings_timeline.php v005 visual cleanup.
 *   - NEW: Creates a timestamped backup before replacing standings_timeline.php.
 *
 * PHP: 7.3 compatible.
 */

declare(strict_types=1);

header('Content-Type: text/plain; charset=UTF-8');

$target = __DIR__ . '/standings_timeline.php';
$payloadBase64 = '';
$payload = base64_decode($payloadBase64, true);

if ($payload === false || trim($payload) === '') {
    http_response_code(500);
    echo "MRL Standings Timeline v005 Installer
";
    echo "FAILED — installer payload could not be decoded.
";
    exit;
}

if (!is_dir(__DIR__)) {
    http_response_code(500);
    echo "MRL Standings Timeline v005 Installer
";
    echo "FAILED — install folder does not exist.
";
    exit;
}

$report = [];

if (is_file($target)) {
    $backup = $target . '.bak_' . date('Ymd_His');
    if (!@copy($target, $backup)) {
        http_response_code(500);
        echo "MRL Standings Timeline v005 Installer
";
        echo "FAILED — could not create backup for standings_timeline.php.
";
        exit;
    }
    $report[] = 'Backup created: ' . basename($backup);
}

$tmp = $target . '.tmp_' . date('Ymd_His');
if (@file_put_contents($tmp, $payload, LOCK_EX) === false) {
    http_response_code(500);
    echo "MRL Standings Timeline v005 Installer
";
    echo "FAILED — could not write temporary file.
";
    exit;
}

if (!@rename($tmp, $target)) {
    @unlink($tmp);
    http_response_code(500);
    echo "MRL Standings Timeline v005 Installer
";
    echo "FAILED — could not replace standings_timeline.php.
";
    exit;
}

$report[] = 'Updated: standings_timeline.php';
$report[] = 'Installed standings_timeline.php v005 audit-style visual cleanup.';

echo "MRL Standings Timeline v005 Installer
";
echo "SUCCESS — standings_timeline.php v005 was installed.

";
echo "Report
";
foreach ($report as $line) {
    echo $line . "
";
}
echo "After a successful install, open standings_timeline.php, then delete this installer.
";
